-- 프로토타입 위키(6장) → wiki_pages 일괄 이식. 한 번만 실행하세요(재실행 시 id 충돌 오류가 나면 이미 실행된 것).
insert into wiki_pages (id, user_id, section, title, definition, points, flagged)
select v.id, u.id, v.section, v.title, v.definition, v.points, v.flagged
from (values
  ('f4625f6f-5f7e-5eb2-9d7e-5a63a79d5368'::uuid, '6장 · 1절 · 공정관리 · 공정표의종류', '공정관리', '정해진 공기 안에 공사를 완성하도록 작업 순서·기간·자원을 계획하고 진도를 통제하는 관리.', '["흐름: 계획(공정표 작성) - 실시 - 진도 측정 - 만회 대책 — 관리의 PDCA가 그대로 적용."]'::jsonb, false),
  ('f0d43552-3eaa-52e2-b949-a11cb45908af'::uuid, '6장 · 1절 · 공정관리 · 공정표의종류', '바차트 (간트차트)', '작업을 세로로 나열하고 기간을 가로 막대로 그린 공정표.', '["장점: 작성 쉽고 직관적. 단점: 작업 간 선후관계·주공정을 알 수 없음 — 지연이 전체에 미치는 영향 파악 불가."]'::jsonb, false),
  ('8f6a4528-ecb1-51fc-99b4-bc3cdf49b1a0'::uuid, '6장 · 1절 · 공정관리 · 공정표의종류', '네트워크공정표', '작업(액티비티)을 화살표·노드로 연결해 선후관계를 표현한 공정표(PERT·CPM).', '["주공정·여유시간 계산 가능 — 대형·복잡 공사의 표준.", "비교·암기 — 바차트(간단·소규모) ↔ 네트워크(관계·대규모) — ''무엇이 늦으면 전체가 늦나''를 아는 것이 네트워크의 가치."]'::jsonb, false),
  ('f689470b-f84e-5b07-86b3-564dcae1fc76'::uuid, '6장 · 1절 · 공정관리 · 공정표의종류', 'PERT · CPM', 'PERT: 신규 사업 — 3점 시간 추정(낙관·정상·비관)으로 확률적 공기 산정. CPM: 경험 있는 반복 공사 — 1점 추정+비용 연계(공기단축).', '["비교·암기 — ''PERT는 처음이라 불확실(확률), CPM은 해봐서 안다(비용)'' — 출제 단골 비교."]'::jsonb, false),
  ('0fd87cd9-e5ba-52c0-a5dd-c901219de1d9'::uuid, '6장 · 1절 · 공정관리 · 네트워크의기초용어', '액티비티 · 이벤트(노드)', '액티비티: 시간·자원이 드는 작업(화살표). 이벤트: 작업의 시작·종료 시점(원). ADM(화살형)·PDM(노드형) 표기.', '[]'::jsonb, false),
  ('c93b5b1e-8d44-5ccd-a1f9-ffd12577a8c7'::uuid, '6장 · 1절 · 공정관리 · 네트워크의기초용어', '더미 (Dummy)', '시간·자원이 없는 점선 화살표. 작업 간 선후관계만 표시하기 위한 가상 작업.', '[]'::jsonb, false),
  ('7542113f-9df5-55fc-9c88-b41c8764957a'::uuid, '6장 · 1절 · 공정관리 · 네트워크의기초용어', 'EST · EFT · LST · LFT', '가장 빠른 개시(EST)·종료(EFT), 가장 늦은 개시(LST)·종료(LFT).', '["전진 계산으로 E계열, 후진 계산으로 L계열 — 이 네 값에서 여유(플로트)가 나옴."]'::jsonb, false),
  ('39e5e459-e367-5e8b-a19b-3f5716f2bf7b'::uuid, '6장 · 1절 · 공정관리 · 네트워크의기초용어', '플로트 (TF · FF · DF)', '작업의 여유시간. TF(전체여유): 전체 공기에 영향 없이 지연 가능한 최대. FF(자유여유): 후속 작업의 EST에 영향 없이 지연 가능. DF(간섭여유): TF-FF.', '["TF=0인 작업의 연결이 주공정선."]'::jsonb, false),
  ('257e8c24-4e0b-536b-a82f-c85f866e2727'::uuid, '6장 · 1절 · 공정관리 · 네트워크의기초용어', '주공정선 (CP, Critical Path)', '여유가 0인 작업들로 이어진 가장 긴 경로 — 이 경로의 길이가 곧 전체 공기.', '["관리 의미: CP 작업의 지연 = 전체 지연. 공기단축도 CP를 줄여야만 효과.", "비교·암기 — ''가장 긴 경로가 공기를 결정한다'' — 면접에서 CPM 한 줄 정의로 이만한 답이 없음."]'::jsonb, false),
  ('85889733-9fa4-5a2c-b561-1ba26e7a0c0c'::uuid, '6장 · 1절 · 공정관리 · 공기단축과진도관리', '공기단축', '목표 공기 초과 시(또는 지연 만회) 자원을 더 투입해 공기를 줄이는 활동. 대상은 반드시 주공정선 작업.', '["방법: 작업 병행(패스트트랙), 돌관(인력·장비 증투입), 공법 변경."]'::jsonb, false),
  ('84292176-9b55-5e01-a5d5-0e9a8a059a06'::uuid, '6장 · 1절 · 공정관리 · 공기단축과진도관리', '비용구배 (Cost Slope)', '공기 1일 단축에 드는 추가 비용 = (급속비용-정상비용) / (정상공기-급속공기).', '["비용구배가 작은 작업부터 단축하는 것이 경제적."]'::jsonb, false),
  ('8f7a5f3f-f936-5f6a-9c06-b8dde2149667'::uuid, '6장 · 1절 · 공정관리 · 공기단축과진도관리', 'MCX (최소비용 공기단축)', '주공정선 상에서 비용구배가 가장 작은 작업부터 단축을 반복해 최소 비용으로 목표 공기를 맞추는 기법.', '["직접비는 늘고 간접비는 줄어 — 총비용 최소점이 최적 공기라는 그림과 세트."]'::jsonb, false),
  ('8541e116-ba21-5030-9e05-c271a61bcb1c'::uuid, '6장 · 1절 · 공정관리 · 공기단축과진도관리', '진도관리 S커브 (바나나곡선)', '누적 진도(기성)를 시간축에 그린 S자 곡선. 허용 상·하한선 사이(바나나 모양) 안에 실적이 있으면 정상.', '["하한선 아래 = 지연(만회 대책), 상한선 위 = 과속(품질·자금 점검)."]'::jsonb, false),
  ('683ad6b1-cea2-53e9-bf82-502da82f521f'::uuid, '6장 · 1절 · 공정관리 · 공기단축과진도관리', '자원배당 · 산붕도', '인력·장비가 특정 시기에 몰리지 않게 여유시간을 이용해 평준화(leveling)하는 것. 산붕도: 자원 투입량의 시간 분포 그래프 — 산처럼 솟은 피크를 깎는 작업.', '[]'::jsonb, false),
  ('f66800de-3c36-595c-ae2e-75727260ae8c'::uuid, '6장 · 1절 · 공정관리 · 공기단축과진도관리', 'LOB (Line of Balance)', '반복 작업(아파트 층별 등)의 진도를 사선으로 표현하는 공정 기법. 작업 간 간격·속도 균형 관리.', '[]'::jsonb, false),
  ('d9f8792b-89e4-5284-9d1d-6554cf5d21a5'::uuid, '6장 · 1절 · 공정관리 · 공기단축과진도관리', '마일스톤', '공정의 주요 관리 시점(착공·골조 완료·상량·준공 등). 계약·보고의 기준점.', '[]'::jsonb, false),
  ('ff85e167-b95c-5ad7-90e4-f18f062d905a'::uuid, '6장 · 1절 · 공정관리 · 공기단축과진도관리', '돌관공사', '인력·장비를 집중 투입해 밤낮없이 진행하는 공사. 지연 만회 수단 — 비용 급증+품질·안전 리스크 동반(사고 다발 조건).', '[]'::jsonb, false),
  ('740adc3c-fc57-5ea6-9f37-ffd08a60e925'::uuid, '6장 · 2절 · 원가관리 · 공사비의구조', '공사비 구성 (직접비 · 간접비)', '직접공사비(재료비+노무비+경비 중 직접분) + 간접공사비(현장관리비 등) + 일반관리비 + 이윤 = 총공사비.', '["''공사비 나무''를 그려 외우기: 몸통(직접비) 위에 간접비·일반관리비·이윤이 얹히는 구조."]'::jsonb, false),
  ('fda6decd-8151-5fb8-8850-92cdfcd81daa'::uuid, '6장 · 2절 · 원가관리 · 공사비의구조', '재료비 · 노무비 · 경비', '공사비 3요소. 경비는 재료·노무 외 비용(장비·전력·가설·보험 등).', '[]'::jsonb, false),
  ('65b076b0-83d0-5f56-9f9e-61d9e461ef45'::uuid, '6장 · 2절 · 원가관리 · 공사비의구조', '일반관리비 · 이윤', '본사 운영비(일반관리비)와 기업 이윤. 요율로 계상. ※요율 확인.', '[]'::jsonb, true),
  ('9843e67a-6d07-5815-82e9-654b70304929'::uuid, '6장 · 2절 · 원가관리 · 적산과견적', '적산과 견적', '적산: 도면·시방서로 공사 수량을 산출하는 기술적 작업. 견적: 수량에 단가를 곱해 공사비를 산정하는 작업.', '["비교·암기 — ''적산은 수량(양), 견적은 금액(돈)'' — 적산 후 견적. 최다 출제 비교."]'::jsonb, false),
  ('2d0cf8c9-eaa7-55f8-8edd-081f35d49ccb'::uuid, '6장 · 2절 · 원가관리 · 적산과견적', '명세견적 · 개산견적', '명세견적: 완성 도면으로 항목별 상세 산출 — 정확·시간 소요. 개산견적: 기획 단계에서 개략 산정(면적당·용적당 단가, 유사 실적) — 빠름·오차 큼.', '[]'::jsonb, false),
  ('b4b950cf-49e6-52da-9be6-ad6d7531eb0b'::uuid, '6장 · 2절 · 원가관리 · 적산과견적', '품셈 · 일위대가', '품셈: 단위 수량당 소요 자원량 기준. 일위대가: 품셈+단가로 만든 단위 작업당 단가표.', '["일위대가표의 합이 내역서 단가가 되는 구조 — ''품셈에서 일위대가로, 일위대가에서 내역서로''."]'::jsonb, false),
  ('cec589f1-6831-53a7-aa10-138f7c36b78f'::uuid, '6장 · 2절 · 원가관리 · 적산과견적', '물량내역서 (BOQ)', '공종별 수량을 담은 내역서. 내역입찰에서 발주자가 교부 — 입찰자는 단가만 기입.', '[]'::jsonb, false),
  ('3ccf0746-d113-56df-9679-91a8656f597f'::uuid, '6장 · 2절 · 원가관리 · 적산과견적', '실행예산', '낙찰 후 시공자가 실제 시공 계획에 맞춰 다시 짠 내부 예산(실행).', '["도급금액과 실행예산의 차이가 목표 이익 — 현장 원가관리의 기준선."]'::jsonb, false),
  ('45f4e65c-6d0e-5aa1-bbb1-5242af449e88'::uuid, '6장 · 2절 · 원가관리 · 적산과견적', '기성고 · 기성청구', '기성고: 현재까지 완성한 공사량(금액). 기성청구: 그만큼 공사비를 청구·수금하는 절차(월별 등). 현금 흐름 관리의 핵심.', '[]'::jsonb, false),
  ('07c4daaa-acb3-561b-b5ad-abec6c4ac079'::uuid, '6장 · 2절 · 원가관리 · 성과와가치', 'EVMS (PV · EV · AC)', '계획가치(PV)·달성가치(EV)·실투입비(AC)를 비교해 일정·비용 성과를 동시에 재는 기법.', '["EV-PV = 일정 편차, EV-AC = 비용 편차 — ''계획만큼 했나, 돈은 그만큼만 썼나''를 숫자로."]'::jsonb, false),
  ('94cebc42-a8b5-52b7-90e3-3781841f74b0'::uuid, '6장 · 2절 · 원가관리 · 성과와가치', 'VE (가치공학)', '가치 = 기능/비용. 필요한 기능을 유지·향상하면서 비용을 낮추는 체계적 대안 검토 활동.', '["비교·암기 — 단순 원가절감(기능 희생 가능)과 구분 — VE는 ''기능 분석''이 본질. 설계 VE 제도화(일정 규모 이상 의무 ※확인)."]'::jsonb, true),
  ('87c8c9bd-8c59-5d7a-8f2e-b72a54963805'::uuid, '6장 · 2절 · 원가관리 · 성과와가치', 'LCC (생애주기비용)', '기획–설계–시공–유지관리–해체까지 전 생애 비용의 합.', '["초기비 10~20%, 유지관리비가 대부분 — ''싸게 짓는 것''과 ''싸게 쓰는 것''은 다르다는 논리. VE 판단의 기준 비용."]'::jsonb, false),
  ('bf953a22-689b-55bb-9ab4-bc942e7cd087'::uuid, '6장 · 2절 · 원가관리 · 성과와가치', '원가절감과 손익분기', '실행 대비 원가 개선 활동(공법 개선·손실 제거·자재 관리). 손익분기: 수익=비용이 되는 지점 — 현장 채산성의 기준.', '[]'::jsonb, false),
  ('ee42bf9d-f648-58c6-a5df-86b73c17bbbb'::uuid, '6장 · 3절 · 품질관리 · 품질의개념', '품질관리 (QC)', '시공 결과가 요구 품질(설계도서·시방 기준)에 맞는지 시험·검사로 확인·시정하는 활동.', '[]'::jsonb, false),
  ('0acd39ae-fc85-5458-a993-09a689880543'::uuid, '6장 · 3절 · 품질관리 · 품질의개념', '품질보증 (QA)', '품질이 확보되도록 절차·시스템을 계획하고 그 증거를 남기는 활동.', '["비교·암기 — QC(결과를 검사) ↔ QA(과정을 보증) — ''검사원의 눈 vs 시스템의 틀''."]'::jsonb, false),
  ('e069400f-79ae-5408-a08a-502168b37779'::uuid, '6장 · 3절 · 품질관리 · 품질의개념', '품질경영 (TQM)', '경영 차원에서 전 부문·전원이 참여하는 총체적 품질 활동. QC-QA-TQM으로 범위가 확장되는 계보.', '[]'::jsonb, false),
  ('396f2d57-976d-5c04-9a72-da7f42750808'::uuid, '6장 · 3절 · 품질관리 · 품질의개념', 'PDCA 사이클', 'Plan(계획)-Do(실시)-Check(확인)-Act(조치)의 반복 개선 고리.', '["품질뿐 아니라 안전·공정관리 전반의 공통 언어 — ''관리란 곧 PDCA를 돌리는 일''."]'::jsonb, false),
  ('d97d5403-09df-5ebf-8454-1550cf0e2edb'::uuid, '6장 · 3절 · 품질관리 · QC7가지도구', '파레토도', '불량·하자 항목을 크기순으로 늘어놓고 누적 비율을 겹친 그래프.', '["''소수의 원인이 대부분의 결과를 만든다(80:20)'' — 중점관리 대상 선정 도구."]'::jsonb, false),
  ('8c127a5f-3711-5e7e-ade9-3fd5b0e37826'::uuid, '6장 · 3절 · 품질관리 · QC7가지도구', '특성요인도 (어골도)', '결과(특성)에 영향을 주는 원인을 생선뼈 모양으로 정리한 그림.', '["4M(사람·기계·재료·방법)으로 가지를 치는 것이 표준 — 하자 원인 분석의 기본 틀."]'::jsonb, false),
  ('16bd4162-0c10-5b23-a4e9-5ca13f11110e'::uuid, '6장 · 3절 · 품질관리 · QC7가지도구', '히스토그램', '데이터 분포를 막대로 나타낸 그림. 규격 상·하한과 겹쳐 공정 능력(치우침·산포)을 봄.', '[]'::jsonb, false),
  ('96af77b1-edbf-5d1e-ac5a-642fa58bef17'::uuid, '6장 · 3절 · 품질관리 · QC7가지도구', '체크시트', '데이터를 항목별로 간단히 수집·집계하는 표. 7도구의 출발점.', '[]'::jsonb, false),
  ('7bd1d82a-c223-5f07-adb7-a900bd610c5c'::uuid, '6장 · 3절 · 품질관리 · QC7가지도구', '산점도 (산포도)', '두 변수의 상관관계를 점으로 찍은 그림(예: W/C비와 강도).', '[]'::jsonb, false),
  ('a40d881b-cb63-5efc-a984-0d6df3d1dceb'::uuid, '6장 · 3절 · 품질관리 · QC7가지도구', '층별', '데이터를 조건별(작업조·기계·시간대)로 나눠 비교하는 방법. 원인이 어디 있는지 좁혀줌.', '[]'::jsonb, false),
  ('7b5e781a-7b50-52fb-8a85-85da39e888c8'::uuid, '6장 · 3절 · 품질관리 · QC7가지도구', '관리도', '시간 순 데이터에 관리한계선(UCL·LCL)을 그어 공정의 안정 여부를 감시하는 그래프.', '["한계선 밖 점·연속 상승 등 이상 신호 시 원인 조사 — ''우연 변동과 이상 변동의 구분''이 본질."]'::jsonb, false),
  ('1bad1246-77ac-548d-9562-82dd79a979ac'::uuid, '6장 · 3절 · 품질관리 · 검사와시스템', '표본검사 · 전수검사', '표본검사: 일부만 뽑아 판정(파괴 시험·대량). 전수검사: 전부 검사(치명 결함·소량).', '["콘크리트 압축강도는 표본(공시체), 고장력볼트 조임·용접 외관은 전수 성격 — 대상에 따라 갈림."]'::jsonb, false),
  ('228815b9-3564-5bc5-9401-783d66308b13'::uuid, '6장 · 3절 · 품질관리 · 검사와시스템', 'ISO 9001', '품질경영시스템 국제 표준. 문서화된 절차·기록으로 품질을 보증 — 입찰 PQ 가점 요소.', '[]'::jsonb, false),
  ('81f4929a-0215-5c65-bd07-a189ad9385b2'::uuid, '6장 · 3절 · 품질관리 · 검사와시스템', '중점품질관리 항목', '하자 빈도·영향이 큰 공종을 선정해 집중 관리(예: 방수, 결로, 층간소음, 균열). 현장 품질계획서의 핵심 — ''다 잘하기보다 아픈 곳을 정해 지킨다''.', '[]'::jsonb, false),
  ('78b45876-4891-5e48-bddd-ae86c3f775bc'::uuid, '6장 · 4절 · 안전관리 · 법과제도', '산업안전보건법', '산업재해 예방과 쾌적한 작업환경 조성을 위한 기본법. 사업주 의무·안전보건관리체제·교육·보호구·도급인 책임 등을 규정.', '["건설 현장 안전관리의 뼈대 — 이하 제도 대부분의 근거법."]'::jsonb, false),
  ('48480778-f203-5d19-8db8-dc61924684ab'::uuid, '6장 · 4절 · 안전관리 · 법과제도', '중대재해처벌법', '중대산업재해 발생 시 경영책임자 처벌을 규정한 법. 안전보건관리체계 구축·이행 의무가 핵심.', '["처벌이 아닌 ''체계 구축 의무''가 본질이라는 프레임으로 답하면 좋은 인상. ※적용 범위 확인."]'::jsonb, true),
  ('b33995e7-f6f3-5f29-8060-f2b75c0f5653'::uuid, '6장 · 4절 · 안전관리 · 법과제도', '안전관리계획서', '건설기술진흥법에 따라 일정 규모·위험 공사에서 착공 전 수립·승인받는 안전관리 계획. ※대상 확인.', '["비교·암기 — 안전관리계획서(건진법 — 구조물·공사 안전) ↔ 유해위험방지계획서(산안법 — 근로자 안전) — 근거법·초점이 다른 짝. 실무 최다 혼동."]'::jsonb, true),
  ('1690e64c-789e-576b-8ca8-cc8e66ea41d9'::uuid, '6장 · 4절 · 안전관리 · 법과제도', '유해위험방지계획서', '산업안전보건법에 따라 일정 규모 이상 건설공사 착공 전 제출하는 근로자 유해·위험 방지 계획. ※대상 공사 확인.', '[]'::jsonb, true),
  ('cdcbf3e3-abc0-5e30-a467-29df75c00295'::uuid, '6장 · 4절 · 안전관리 · 법과제도', '위험성평가', '유해·위험요인을 찾아(파악) 위험성을 추정·결정하고 감소대책을 수립·실행하는 절차. 사업주 의무.', '["위험성 = 가능성(빈도) x 중대성(강도). 절차: 사전준비 - 요인 파악 - 추정 - 결정 - 대책 - 기록. 수시·정기 실시. ※최신 고시 확인."]'::jsonb, true),
  ('0aa19384-8daf-5013-8b46-fd6b190cf76d'::uuid, '6장 · 4절 · 안전관리 · 법과제도', '산업안전보건관리비', '공사금액에 요율을 곱해 계상하는 안전 전용 비용. 안전시설·보호구·안전관리자 인건비 등에만 사용(목적 외 사용 금지).', '["''안전은 공짜가 아니라 계상된 돈으로 한다'' — 요율·사용 기준 ※확인."]'::jsonb, true),
  ('4e5ac9f8-684d-59a6-bebe-f4082edbf178'::uuid, '6장 · 4절 · 안전관리 · 법과제도', '안전관리자 · 관리감독자', '안전관리자: 안전 기술 지도·보좌 전문 인력(공사 규모별 선임 ※확인). 관리감독자: 생산 라인의 직장·반장 — 자기 라인의 안전 점검 의무를 지는 사람.', '["비교·암기 — ''안전관리자는 참모, 관리감독자는 야전 지휘관'' — 직접 지휘 라인에 안전 의무를 얹은 것이 관리감독자 제도의 취지."]'::jsonb, true),
  ('b9018635-5c1d-5282-b9a7-742c7e8f6288'::uuid, '6장 · 4절 · 안전관리 · 법과제도', '안전보건총괄책임자', '도급 현장에서 원·하청 전체의 안전보건을 총괄하는 책임자(보통 현장소장). 도급인 책임 강화의 축.', '[]'::jsonb, false),
  ('61e0a7b0-5f20-5523-899d-2c3619061e91'::uuid, '6장 · 4절 · 안전관리 · 법과제도', 'TBM (툴박스미팅)', '작업 직전 현장에서 당일 작업의 위험과 대책을 공유하는 짧은 회의. 위험성평가를 작업자에게 전달하는 마지막 관문.', '[]'::jsonb, false),
  ('9491b79b-fc54-5f8b-b909-b1b11dd28b19'::uuid, '6장 · 4절 · 안전관리 · 재해이론왜사고가나는가', '아차사고 (Near Miss)', '다치지는 않았지만 다칠 뻔한 사건. 중대재해의 전조 — 신고·분석 문화가 예방의 핵심.', '[]'::jsonb, false),
  ('c97e4f62-59c2-5048-809f-79be99718bdf'::uuid, '6장 · 4절 · 안전관리 · 재해이론왜사고가나는가', '하인리히 법칙 (1:29:300)', '중상 1건 뒤에 경상 29건, 무상해 사고 300건이 있다는 경험 법칙.', '["메시지: 밑바닥의 300(아차사고)을 관리하면 꼭대기의 1(중대재해)을 막는다."]'::jsonb, false),
  ('42868185-30c2-5e8c-9a87-bf56a706f202'::uuid, '6장 · 4절 · 안전관리 · 재해이론왜사고가나는가', '버드 법칙 (1:10:30:600)', '중상 1 : 경상 10 : 물적손실 30 : 아차사고 600의 비율. 하인리히를 확장 — 물적 손실 사고까지 포함.', '["비교·암기 — 하인리히(1:29:300) vs 버드(1:10:30:600) — 숫자 세트만 정확히. 버드는 ''손실 통제(관리 부재가 근본 원인)'' 강조."]'::jsonb, false),
  ('9ecdd7f7-46cd-501c-aafe-abf4f9282431'::uuid, '6장 · 4절 · 안전관리 · 재해이론왜사고가나는가', '도미노 이론', '재해는 5단계 연쇄(사회적 환경·유전 - 개인 결함 - 불안전 행동·상태 - 사고 - 재해)로 발생한다는 이론.', '["하인리히: 3단계(불안전 행동·상태)를 빼면 연쇄가 끊긴다 — 직접 원인 제거론. 버드는 관리(통제) 부족을 근원에 둠."]'::jsonb, false),
  ('1fa7df29-faf8-5b13-a424-3135230141e2'::uuid, '6장 · 4절 · 안전관리 · 재해이론왜사고가나는가', '불안전한 행동 · 상태', '행동(사람 요인: 보호구 미착용·무리한 작업)과 상태(물적 요인: 방호 미비·결함 설비).', '["재해의 직접 원인 양대 축 — 통계상 불안전 행동 비중이 큼. 대책도 사람(교육·관리)과 물(설비·시설)의 양면으로."]'::jsonb, false),
  ('65b9cadd-a513-5157-b063-4a111b681d2b'::uuid, '6장 · 4절 · 안전관리 · 재해이론왜사고가나는가', '연천인율 · 도수율 · 강도율', '연천인율: 근로자 1000명당 연간 재해자 수. 도수율: 100만 근로시간당 재해 건수. 강도율: 1000 근로시간당 근로손실일수.', '["비교·암기 — ''도수율은 빈도(몇 번), 강도율은 심각도(며칠 잃었나)'' — 분모(시간)와 분자(건수/손실일)를 구분해 암기. 산식 ※확인."]'::jsonb, true),
  ('15b7dcda-7ab0-5948-ad30-d5c4411de4c1'::uuid, '6장 · 4절 · 안전관리 · 재해유형별예방건설5대재해', '추락재해 예방', '건설 사망재해 1위. 대책 우선순위: 작업 자체 제거·변경 - 추락 방지 시설(난간·발판·방호망) - 개인 보호(안전대) 순.', '["''시설이 먼저, 안전대는 마지막 수단'' — 안전대는 걸 곳(부착설비)이 있어야 의미."]'::jsonb, false),
  ('c43dab84-51e8-515e-a10a-8018f0202087'::uuid, '6장 · 4절 · 안전관리 · 재해유형별예방건설5대재해', '낙하 · 비래', '위에서 떨어지는 물체(낙하)와 날아오는 물체(비래)에 의한 재해.', '["대책: 낙하물방지망·방호선반·출입통제·달줄 사용(던지기 금지)."]'::jsonb, false),
  ('c34edc6d-7f15-57d2-8454-f5e66b438cad'::uuid, '6장 · 4절 · 안전관리 · 재해유형별예방건설5대재해', '협착 · 감김', '장비·기계에 끼이는 재해(지게차·굴착기·회전체).', '["대책: 작업반경 출입통제, 유도자, 방호덮개, 정비 시 전원 차단(LOTO)."]'::jsonb, false),
  ('dc8c684b-caaf-53d0-86d8-e60ab9c037de'::uuid, '6장 · 4절 · 안전관리 · 재해유형별예방건설5대재해', '감전재해', '전기 접촉 재해.', '["대책: 접지·누전차단기, 충전부 방호, 가공전선 접근 한계(장비 붐), 젖은 손 취급 금지."]'::jsonb, false),
  ('1b94707f-46c4-505d-bdf5-580e13ba06cb'::uuid, '6장 · 4절 · 안전관리 · 재해유형별예방건설5대재해', '붕괴재해', '흙막이·동바리·비계·구조물의 무너짐.', '["대책: 구조검토·조립도 준수, 해체 순서 준수, 계측, 지반·기초 확인 — 1~2장의 가시설 지식과 직결."]'::jsonb, false),
  ('501a187f-e12f-5eee-ab6e-0c06dd63f717'::uuid, '6장 · 4절 · 안전관리 · 재해유형별예방건설5대재해', '밀폐공간 질식', '맨홀·탱크·정화조 등 산소결핍·유해가스 공간의 질식 재해.', '["대책: 작업 전 산소·가스 농도 측정(산소 18~23.5% ※확인), 환기, 감시인, 송기마스크 — ''측정 없이 진입 금지''."]'::jsonb, true),
  ('33a9d00f-71e7-5d01-87e0-f7d25f45f474'::uuid, '6장 · 4절 · 안전관리 · 보호구작업관리', '안전대 · 안전모 · 보호구', '개인 보호구(PPE). 추락(안전대·안전모), 물체(안전화·안전모), 유해물(방진·방독마스크) — 최후의 방어선이라는 위상.', '[]'::jsonb, false),
  ('6991b9a2-6547-5db3-a486-6f9b249f3703'::uuid, '6장 · 4절 · 안전관리 · 보호구작업관리', '안전인증 (KCs)', '위험 기계·보호구의 안전 인증 제도. 인증 제품 사용 의무 — 미인증 보호구는 보호구가 아님.', '[]'::jsonb, false),
  ('0e7cec7b-d5df-530b-8bd1-be60201dce79'::uuid, '6장 · 4절 · 안전관리 · 보호구작업관리', '신호수 · 유도자', '장비 작업 반경의 접촉 사고를 막는 배치 인력. 크레인 인양·차량 후진·도로 출입 시 필수.', '[]'::jsonb, false),
  ('b4b2589a-c07a-55df-bf2b-67f6d0be9937'::uuid, '6장 · 4절 · 안전관리 · 보호구작업관리', '작업계획서 (중장비)', '차량계 건설기계·하역기계 사용 전 작성하는 작업계획(작업 방법·경로·유도자 배치). 지게차·굴착기·크레인 등 대상. ※대상 확인.', '[]'::jsonb, true),
  ('23608e81-d35f-5e9c-85ef-d967564c8536'::uuid, '6장 · 4절 · 안전관리 · 보호구작업관리', '작업중지권', '산재 위험이 급박할 때 근로자가 작업을 중지하고 대피할 수 있는 권리. 사업주는 불이익 처우 금지.', '["사업주의 작업중지 의무와 근로자의 작업중지권 양 방향 — 안전 문화의 지표로 답하기 좋은 소재."]'::jsonb, false),
  ('a27a2ca6-f674-5141-997d-4968d63c0897'::uuid, '6장 · 4절 · 안전관리 · 보호구작업관리', '안전보건교육', '정기·채용 시·작업내용 변경 시·특별교육(위험 작업). 대상·시간 규정 ※확인 — 교육은 형식이 아니라 TBM과 연결될 때 산다는 관점.', '[]'::jsonb, true),
  ('f5dcd7d5-da41-5daa-a749-895811c496cf'::uuid, '6장 · 4절 · 안전관리 · 보호구작업관리', 'MSDS (물질안전보건자료)', '화학물질의 유해성·취급법·응급조치를 담은 자료. 게시·비치, 취급 근로자 교육 의무 — 도장·방수·용접 등 화학물질 공종과 직결.', '[]'::jsonb, false),
  ('f090de60-a87a-5ce7-862a-883a8cd03135'::uuid, '6장 · 5절 · 준공유지관리신기술 · 준공절차', '사용승인 · 준공검사', '공사 완료 후 허가권자에게 적법 시공을 확인받아 건물 사용 자격을 얻는 절차(0장 인허가 3단계의 마지막).', '["감리완료보고서·각종 필증(소방·승강기 등)이 갖춰져야 신청 가능."]'::jsonb, false),
  ('85ae5d9e-3ae7-51af-b2f7-a33c1080e73e'::uuid, '6장 · 5절 · 준공유지관리신기술 · 준공절차', '시운전', '설비 시스템(공조·소방·전기·승강기)을 실제 가동해 성능을 확인·조정하는 절차. 시공과 운영을 잇는 다리 — TAB(풍량·수량 측정 조정) 포함.', '[]'::jsonb, false),
  ('ed5a16a5-8feb-5f0d-9bd8-d6442663f13e'::uuid, '6장 · 5절 · 준공유지관리신기술 · 준공절차', '준공도서', '준공 시 인계하는 도서 일체 — 준공도면(as-built), 시방서, 승인서류, 유지관리 지침, 보증서. ''지은 대로 그린 도면''이 핵심.', '[]'::jsonb, false),
  ('8b2b72da-ce49-5eef-a59b-2ad3e8bfb3cc'::uuid, '6장 · 5절 · 준공유지관리신기술 · 하자와유지관리', '하자담보책임', '준공 후 일정 기간 내 발생한 하자를 시공자가 보수할 책임. 공종별 담보 기간(구조체는 길고 마감은 짧음). ※기간표 확인.', '["''기산점(인도일)·기간·범위''가 분쟁의 3대 쟁점."]'::jsonb, true),
  ('90caccc8-4142-5c2f-bb6e-4fd7085a9d15'::uuid, '6장 · 5절 · 준공유지관리신기술 · 하자와유지관리', '하자보수보증금', '하자보수 이행을 담보하는 예치금(보증서). 요율 계상 — 미이행 시 발주자가 직접 보수에 사용. ※요율 확인.', '[]'::jsonb, true),
  ('507aa237-65df-54b7-9c95-3d78f52c0423'::uuid, '6장 · 5절 · 준공유지관리신기술 · 하자와유지관리', '유지관리', '준공 후 성능을 유지하도록 점검·보수·교체하는 활동. LCC의 대부분이 여기서 발생 — ''건물의 수명은 유지관리가 결정''.', '[]'::jsonb, false),
  ('549bafc6-58e0-509f-a4bb-3f7d08de1031'::uuid, '6장 · 5절 · 준공유지관리신기술 · 하자와유지관리', '시설물안전법', '일정 규모 시설물(1·2·3종)의 안전점검·진단을 의무화한 법(시설물의 안전 및 유지관리에 관한 특별법).', '["성수대교·삼풍 붕괴가 제정 배경 — 안전 직무 면접에서 맥락으로 언급하기 좋음. ※종별 기준 확인."]'::jsonb, true),
  ('68d2f192-112e-5a5a-973f-c25a7ddf86a5'::uuid, '6장 · 5절 · 준공유지관리신기술 · 하자와유지관리', '정밀점검 · 정밀안전진단', '정기점검(육안) - 정밀점검(장비 포함, 주기적) - 정밀안전진단(정밀 조사+구조 안전성 평가, 1종 등 의무)의 단계 구조.', '["비교·암기 — ''점검은 상태 확인, 진단은 원인·안전성 평가'' — 깊이가 다른 계단으로 기억."]'::jsonb, false),
  ('d25dc5a9-0a52-5c0d-bced-8856eed2e758'::uuid, '6장 · 5절 · 준공유지관리신기술 · 하자와유지관리', '안전점검', '해빙기·우기·태풍 전후 등 시기별 취약 요인 점검(공사 중)과 시설물 정기 점검(운영 중) 모두를 포괄하는 용어.', '[]'::jsonb, false),
  ('b270cb4f-af72-58e5-92b0-1182241928be'::uuid, '6장 · 5절 · 준공유지관리신기술 · 하자와유지관리', '리모델링', '노후 건물의 성능 개선·증축. 재건축 대비 자원·기간 절감 — 내력벽 등 구조 안전 검토가 필수 전제.', '[]'::jsonb, false),
  ('1e6fafa1-1a65-5d5f-a4ec-8a2ce71bcec3'::uuid, '6장 · 5절 · 준공유지관리신기술 · 해체와환경', '해체공사 · 해체계획서', '건축물 해체 시 허가(신고)와 해체계획서 작성·감리 배치를 의무화한 제도. ※대상 기준 확인.', '["해체 순서 임의 변경이 붕괴 사고의 전형적 원인 — 계획서 준수+감리 확인이 제도의 핵심."]'::jsonb, true),
  ('8e289fc1-ff2d-580d-831f-daaec62b2442'::uuid, '6장 · 5절 · 준공유지관리신기술 · 해체와환경', '압쇄공법 · 발파해체', '압쇄: 압쇄기로 위층부터 눌러 부수는 표준 해체. 발파해체: 화약으로 순간 붕괴 — 고층·특수 조건(주변 안전 확보 시).', '[]'::jsonb, false),
  ('cc231da2-a85a-5566-aa9b-3122b1817a4f'::uuid, '6장 · 5절 · 준공유지관리신기술 · 해체와환경', '석면조사', '해체·철거 전 석면 함유 자재 조사 의무. 함유 시 전문업체가 밀폐·습식으로 선행 제거 — 근로자·주민 건강 직결.', '[]'::jsonb, false),
  ('40cdee10-7c75-552c-90f9-b0d44adf967e'::uuid, '6장 · 5절 · 준공유지관리신기술 · 해체와환경', '건설폐기물 처리', '분별 해체·현장 분리 배출, 위탁 처리(올바로시스템 신고), 순환골재 재활용 — 처리 계획과 비용이 해체공사의 절반.', '[]'::jsonb, false),
  ('8736400a-2117-5893-92c4-ff014c70f023'::uuid, '6장 · 5절 · 준공유지관리신기술 · 스마트건설신기술키워드', '스마트건설', 'BIM·드론·로봇·IoT·모듈러 등 디지털·자동화 기술로 생산성과 안전을 높이는 건설 방식의 총칭.', '["배경: 숙련공 감소·고령화·중대재해 규제 — ''사람이 하던 위험한 일을 기술이 대신한다''는 프레임."]'::jsonb, false),
  ('01f28232-b52e-507b-9feb-69586ea47dc9'::uuid, '6장 · 5절 · 준공유지관리신기술 · 스마트건설신기술키워드', '드론 측량', '드론 사진측량으로 지형·토공량을 신속 산출, 공정 진도·안전 점검에 활용. 접근 위험 구역 점검 대체.', '[]'::jsonb, false),
  ('eca00ee1-dd27-59e9-b9fe-fb93b97ea66b'::uuid, '6장 · 5절 · 준공유지관리신기술 · 스마트건설신기술키워드', 'OSC · 모듈러', '공장 사전 제작+현장 조립을 극대화한 생산방식(Off-Site Construction). 모듈러는 공간 유닛 단위.', '["품질 균일·공기 단축·현장 위험작업 감소 — 안전과 생산성을 함께 답할 수 있는 소재. PC(부재)와 단위 크기로 구분."]'::jsonb, false),
  ('029424b0-ef6b-53b8-aaf8-a57a8c2515fc'::uuid, '6장 · 5절 · 준공유지관리신기술 · 스마트건설신기술키워드', '3D 프린팅 건설', '콘크리트 적층 출력으로 거푸집 없이 구조물 조형. 비정형·소형 구조물 실증 단계.', '[]'::jsonb, false),
  ('e6b62b97-4c0d-56d8-a5b7-13895f006681'::uuid, '6장 · 5절 · 준공유지관리신기술 · 스마트건설신기술키워드', '건설로봇', '앵커 시공·용접·조적·현장 순찰(4족 보행) 등 로봇 적용. 위험·반복 작업 대체 — 협동 안전 기준이 과제.', '[]'::jsonb, false),
  ('bc8e9947-a609-53bc-9cca-dfba2fc53b4b'::uuid, '6장 · 5절 · 준공유지관리신기술 · 스마트건설신기술키워드', 'IoT 안전관리', '스마트 안전장비 — 근로자 위치·생체 센서, 가스·붕괴 감지 센서, 장비 접근 경보(스마트 태그), CCTV·AI 영상 분석. 중대재해 대응 스마트 안전 의무화 흐름. ※확인.', '[]'::jsonb, true),
  ('d98eb322-8944-5633-8468-1db38f6bb32d'::uuid, '6장 · 5절 · 준공유지관리신기술 · 스마트건설신기술키워드', '디지털트윈', '실물 현장·건물을 가상 공간에 동기화한 쌍둥이 모델. 시공 시뮬레이션·유지관리(설비 이력)에 활용 — BIM의 운영 단계 확장으로 이해.', '[]'::jsonb, false)
) as v(id, section, title, definition, points, flagged)
cross join (select id from auth.users limit 1) as u;
